 if(ordinary)return ordinary;
 const high={8:[3,'3rd finger · third position'],9:[3,'High 3rd finger · third position'],10:[1,'1st finger · sixth position'],11:[2,'Low 2nd finger · sixth position'],12:[2,'High 2nd finger · sixth position'],13:[3,'3rd finger · sixth position']}[n.semi];
