function renderPath(){ $('lessonList').innerHTML=levels.map((name,i)=>`<div class="level-group"><p>Level ${i+1} · ${name}</p>${lessons.filter(l=>l.level===i+1).map(l=>`<button class="lesson-button ${l===current?'active':''} ${completed.has(l.id)?'done':''}" data-lesson="${l.id}" ${l===current?'aria-current="step"':''}><span class="number">${completed.has(l.id)?'✓':lessons.indexOf(l)+1}</span><span>${l.title}<small>${l.type}</small></span></button>`).join('')}</div>`).join('');$('completedCount').textContent=completed.size;document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>selectLesson(b.dataset.lesson)); }
function selectLesson(id){stop();if(window.speechSynthesis)window.speechSynthesis.cancel();current=id==='221b'?sherlockLesson:lessons.find(l=>l.id===id);index=0;exploring=false;$('levelLabel').textContent=current.secret?'A SECRET FROM BAKER STREET':`LEVEL ${current.level} · ${levels[current.level-1].toUpperCase()}`;if(current.secret){$('tempo').value=current.tempo;$('tempoValue').textContent=`${current.tempo} BPM`;}document.querySelector('.diagram-heading span').textContent=current.secret?'FINGER VIEW · ADVANCED SHIFTS':current.level>=8?'FINGER VIEW · POSITION SHIFTS':'FINGER VIEW · FIRST POSITION';$('complete').hidden=!!current.secret;$('fullScore').style.maxHeight=current.secret?'65vh':'';$('fullScore').style.overflowY=current.secret?'auto':'';$('mirror').hidden=false;$('lessonTitle').textContent=current.title;$('lessonBadge').textContent=current.type;$('lessonDescription').textContent=current.description;$('steps').innerHTML=current.steps.map(s=>`<li>${s}</li>`).join('');$('goal').textContent=current.goal;updateComplete();renderPath();renderSequence();scoreDirty=true;if(practiceView==='sheet')renderScore();showNote(current.notes[0]);$('playStatus').textContent='Tap any note to see its fingering.';}
function updateComplete(){$('complete').textContent=completed.has(current.id)?'Practiced ✓ · tap to undo':'I practiced this lesson ✓'}
function renderSequence(){ $('sequence').innerHTML=current.notes.map((n,i)=>`<button data-index="${i}" aria-label="Note ${i+1}: ${voices(n).map(v=>`${pitch(v).name}, tab ${tabLabel(v)}, ${fingerLabel(v)}`).join(' and ')}, ${n.beats} beats">${n.rest?'Rest':voices(n).map(v=>pitch(v).name).join('+')}<strong class="tab-label">${n.rest?'—':voices(n).map(tabLabel).join(' + ')}</strong><small>${n.rest?'No playing':voices(n).map(fingerLabel).join(' + ')}</small><small>${n.beats} beat${n.beats===1?'':'s'}</small></button>`).join('');document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{stop();exploring=false;index=Number(b.dataset.index);showNote(current.notes[index]);ensureAudio().then(()=>playTone(current.notes[index]));});}
function fingerboard(n){const vs=voices(n),xs=flipped?[270,210,150,90]:[90,150,210,270];const maxSemi=Math.max(7,...current.notes.flatMap(n=>voices(n).map(v=>v.semi)),...vs.map(v=>v.semi)),extended=maxSemi>7;const y=semi=>80+(1-Math.pow(2,-semi/12))*(extended?350/(1-Math.pow(2,-maxSemi/12)):910);
let svg=`<defs><linearGradient id="board" x2="1" y2="0"><stop stop-color="#202932"/><stop offset=".5" stop-color="#38424b"/><stop offset="1" stop-color="#202932"/></linearGradient></defs><path d="M72 80 L288 80 L309 465 L51 465Z" fill="url(#board)"/><rect x="70" y="74" width="220" height="10" rx="3" fill="#ddd4be"/><text x="320" y="85" font-size="12" fill="#536775">nut</text>`;
(extended?Array.from({length:maxSemi},(_,i)=>i+1):PATTERN.filter(p=>p.semi>0).map(p=>p.semi)).forEach(semi=>svg+=`<line x1="60" x2="300" y1="${y(semi)}" y2="${y(semi)}" stroke="#ffffff" stroke-opacity=".35" stroke-width="2.625" stroke-dasharray="6 5"/>`);
STRINGS.forEach((s,i)=>{let active=vs.some(v=>v.s===i);svg+=`<text x="${xs[i]}" y="45" text-anchor="middle" font-size="21" font-weight="700" fill="${s.color}">${s.name}</text><line x1="${xs[i]}" x2="${xs[i]}" y1="82" y2="${437}" stroke="${active?s.color:'#c0c8cb'}" stroke-width="${active?5:3-i*.5}"/>`;(extended?Array.from({length:maxSemi},(_,j)=>({semi:j+1})):PATTERN.filter(p=>p.semi>0)).forEach(p=>svg+=`<circle cx="${xs[i]}" cy="${y(p.semi)}" r="5" fill="#ffffff"/>`);});
vs.forEach(v=>{let p=pattern(v),cy=p.finger===0?62:y(v.semi);svg+=`<circle class="marker" cx="${xs[v.s]}" cy="${cy}" r="21" fill="${STRINGS[v.s].color}" stroke="white" stroke-width="3"/><text x="${xs[v.s]}" y="${cy+6}" text-anchor="middle" font-size="19" font-weight="700" fill="white">${p.finger}</text>`});$('fingerboard').innerHTML=svg;$('fingerboard').setAttribute('aria-label',n.rest?'Rest: no finger placement':vs.map(v=>`${pitch(v).name}${pitch(v).octave}, ${STRINGS[v.s].name} string, ${pattern(v).placement}`).join('; '));}
function drawStaff(n){if(n.rest){$('staff').innerHTML='<p class="small">Rest · keep counting</p>';return;}let svg='';for(let i=0;i<5;i++)svg+=`<line x1="18" x2="220" y1="${25+i*10}" y2="${25+i*10}" stroke="#9eaeb7"/>`;svg+='<text x="20" y="63" font-size="44" fill="#173746">𝄞</text>';
voices(n).forEach((v,i)=>{let p=pitch(v),degree={C:0,D:1,E:2,F:3,G:4,A:5,B:6}[p.name[0]]+p.octave*7,cy=65-(degree-30)*5,cx=110+i*32;for(let ly=75;ly<=cy;ly+=10)svg+=`<line x1="${cx-13}" x2="${cx+13}" y1="${ly}" y2="${ly}" stroke="#173746"/>`;for(let ly=15;ly>=cy;ly-=10)svg+=`<line x1="${cx-13}" x2="${cx+13}" y1="${ly}" y2="${ly}" stroke="#173746"/>`;svg+=`<ellipse cx="${cx}" cy="${cy}" rx="8" ry="5" transform="rotate(-20 ${cx} ${cy})" fill="${STRINGS[v.s].color}"/><line x1="${cx+7}" x2="${cx+7}" y1="${cy}" y2="${cy-26}" stroke="#173746"/>`;if(p.name.includes('♭'))svg+=`<text x="${cx-23}" y="${cy+5}" font-size="19">♭</text>`;if(p.name.includes('♯'))svg+=`<text x="${cx-23}" y="${cy+5}" font-size="19">♯</text>`});$('staff').innerHTML=`<svg viewBox="${current.secret||current.level>=8?'0 -90 240 185':'0 -10 240 105'}" role="img" aria-label="Pitch reference in treble clef; rhythms appear in the note buttons">${svg}</svg>`;}
function showNote(n){fingerboard(n);drawStaff(n);updateScore(n);$('noteName').innerHTML=n.rest?'Rest':voices(n).map(v=>{let p=pitch(v);return `${p.name}<sub>${p.octave}</sub>`}).join(' + ');$('noteInstruction').innerHTML=n.rest?'<div class="note-instruction">No playing · keep the pulse</div>':voices(n).map(v=>`<div class="note-instruction">${STRINGS[v.s].name} string · ${pattern(v).placement}</div>`).join('');$('fingerKey').innerHTML=voices(n).map(v=>`<span class="finger-pill"><strong>Tab ${tabLabel(v)}</strong> · ${pattern(v).finger===0?'0 · no fingers':`${pattern(v).finger} · ${['','index','middle','ring','pinky'][pattern(v).finger]}`}</span>`).join('');$('technique').textContent=exploring?'Keep your thumb light and your fingers curved. Use your ears to fine-tune the pitch.':current.tip;document.querySelectorAll('[data-index]').forEach(b=>{let active=!exploring&&Number(b.dataset.index)===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('previous').disabled=!exploring&&index===0;$('next').disabled=!exploring&&index===current.notes.length-1;}
