let previousPlayedIndex=-1;
function stop(){previousPlayedIndex=-1;playing=false;clearTimeout(timer);timer=null;stopAudio();$('play').textContent='▶ Play along';}
function tick(){if(!playing)return;let n=current.notes[index],effectiveTempo=Number($('tempo').value)*(current.secret?n.tempo/current.tempo:1),duration=n.beats*60/effectiveTempo;showNote(n);const continuation=index>0&&previousPlayedIndex===index-1&&current.notes[index-1].tie;previousPlayedIndex=index;if(!continuation){let sustained=duration;for(let j=index;current.notes[j].tie&&j+1<current.notes.length;j++)sustained+=current.notes[j+1].beats*60/(Number($('tempo').value)*(current.secret?current.notes[j+1].tempo/current.tempo:1));playTone(n,Math.max(.1,sustained*.98));}$('playStatus').textContent=`Note ${index+1} of ${current.notes.length} · ${n.beats} beat${n.beats===1?'':'s'}`;timer=setTimeout(()=>{if(!playing)return;if(index===current.notes.length-1){if($('loop').checked)index=0;else{stop();$('playStatus').textContent=current.secret?'Case closed! Revisit a phrase or play the theme again.':'Well played! Try it again, or mark this lesson practiced.';return;}}else index++;tick()},duration*1000);}
$('play').onclick=async()=>{if(playing){stop();return}await ensureAudio();if(exploring||index===current.notes.length-1)index=0;exploring=false;playing=true;$('play').textContent='Ⅱ Pause';tick()};
$('previous').onclick=()=>{stop();exploring=false;index=Math.max(0,index-1);showNote(current.notes[index])};$('next').onclick=()=>{stop();exploring=false;index=Math.min(current.notes.length-1,index+1);showNote(current.notes[index])};$('restart').onclick=()=>{stop();exploring=false;index=0;showNote(current.notes[index]);$('playStatus').textContent='Back to the first note.'};
$('tempo').oninput=()=>{$('tempoValue').textContent=`${$('tempo').value} BPM`;if(playing){clearTimeout(timer);stopAudio();tick()}};
$('sound').onchange=async()=>{$('sound').checked?await ensureAudio():stopAudio()};
$('mirror').onclick=()=>{flipped=!flipped;$('mirror').setAttribute('aria-pressed',String(flipped));fingerboard(displayedNote);};
let displayedNote=current.notes[0];const originalShow=showNote;showNote=function(n){displayedNote=n;originalShow(n)};
$('complete').onclick=()=>{if(current.secret)return;completed.has(current.id)?completed.delete(current.id):completed.add(current.id);saveProgress();updateComplete();renderPath()};
$('progressButton').onclick=()=>{$('progressDetail').textContent=`${completed.size} of ${lessons.length} lessons practiced. ${completed.size===lessons.length?'You have explored every lesson!':'Take your time and revisit your favorites.'}`;$('resetMessage').textContent='';$('resetProgress').textContent='Reset progress';$('progressDialog').showModal()};$('closeDialog').onclick=()=>$('progressDialog').close();
let resetArmed=false;$('resetProgress').onclick=()=>{if(!resetArmed){resetArmed=true;$('resetProgress').textContent='Confirm reset';$('resetMessage').textContent='This clears all practiced lessons on this device. Tap Confirm reset to continue.';return}completed.clear();saveProgress();renderPath();updateComplete();$('progressDetail').textContent=`0 of ${lessons.length} lessons practiced.`;$('resetMessage').textContent='Progress reset. You can start fresh.';$('resetProgress').textContent='Reset progress';resetArmed=false};$('progressDialog').addEventListener('close',()=>resetArmed=false);
function explore(n){stop();exploring=true;showNote(n);ensureAudio().then(()=>playTone(n));$('playStatus').textContent='Explorer view · Play along returns to your lesson.';$('fingerboard').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
function renderExplorer(mode){$('notesTab').classList.toggle('selected',mode==='notes');$('chordsTab').classList.toggle('selected',mode==='chords');if(mode==='notes'){$('noteExplorer').innerHTML=STRINGS.map((s,i)=>`<div class="note-row"><strong>${s.name} string</strong>${PATTERN.map(p=>`<button data-string="${i}" data-semi="${p.semi}" aria-label="${pitch(note(i,p.semi)).name}, ${p.placement}">${pitch(note(i,p.semi)).name}<strong class="tab-label">${tabLabel(note(i,p.semi))}</strong><small>${fingerLabel(note(i,p.semi))}</small></button>`).join('')}</div>`).join('');document.querySelectorAll('[data-string]').forEach(b=>b.onclick=()=>explore(note(Number(b.dataset.string),Number(b.dataset.semi))))}else{$('noteExplorer').innerHTML='<p class="small">These are two-note parts of a chord. Bow both highlighted adjacent strings together.</p>'+chords.map((c,i)=>`<div class="note-row"><button data-chord="${i}">${c.name}<strong class="tab-label">${c.voices.map(tabLabel).join(' + ')}</strong><small>${c.voices.map(fingerLabel).join(' + ')}</small></button></div>`).join('');document.querySelectorAll('[data-chord]').forEach(b=>b.onclick=()=>explore(chords[Number(b.dataset.chord)]))}}
$('notesTab').onclick=()=>renderExplorer('notes');$('chordsTab').onclick=()=>renderExplorer('chords');document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});


let practiceView='finger',scoreDirty=true,scoreSegments=[],scoreKey='',scoreNodes=[];
function abcPitch(n,accidentals){const p=pitch(n),letter=p.name[0],oct=p.octave;let abc=oct>=5?letter.toLowerCase():letter;abc+=oct>5?"'".repeat(oct-5):oct<4?','.repeat(4-oct):'';const key=letter+oct,sharp=p.name.includes('♯'),previous=accidentals.get(key)||false;let prefix=sharp===previous?'':sharp?'^':'=';accidentals.set(key,sharp);return prefix+abc;}
function abcDuration(beats){return beats===1?'':Number.isInteger(beats)?String(beats):Number.isInteger(beats*2)?`${beats*2}/2`:`${beats*4}/4`;}
function buildScore(notes,title,barsPerLine){let abc=`X:1\nT:${title}\nM:4/4\nL:1/4\nK:C clef=treble\n`,beat=0,bar=0,accidentals=new Map(),segments=[];notes.forEach((n,sourceIndex)=>{let remaining=n.beats||1,first=true;while(remaining>0){const duration=Math.min(remaining,4-beat),tones=voices(n).map(v=>abcPitch(v,accidentals)),symbol=tones.length===1?tones[0]:`[${tones.join('')}]`,label=voices(n).map(tabLabel).join(' + '),start=abc.length;abc+=(first?`"^${label}"`:'')+(first&&n.slurStart?'(':'')+symbol+abcDuration(duration);remaining-=duration;if(remaining>0)abc+='-';else if(n.slurEnd)abc+=')';segments.push({sourceIndex,start,end:abc.length,duration});abc+=' ';first=false;beat+=duration;if(beat>=4){abc+='| ';beat=0;bar++;accidentals.clear();if(bar%barsPerLine===0)abc+='\n';}}});abc=abc.trimEnd();if(beat===0)abc=abc.replace(/\|\s*$/,'');abc+='|]';return {abc,segments};}
function buildSherlockScore(title,barsPerLine){
 let abc=`X:1\nT:${title}\nC:Patrick Gowers\nM:3/4\nL:1/4\nQ:1/4=77\nK:Bb clef=treble\n`,segments=[],sourceIndex=0,lastMeter='3/4',lastTempo=77,accidentals=new Map();
 for(const measure of SHERLOCK_MEASURES){
  if(measure.meter!==lastMeter){abc+=`[M:${measure.meter}] `;lastMeter=measure.meter;}
  if(measure.tempo!==lastTempo){abc+=`[Q:1/4=${measure.tempo}] `;lastTempo=measure.tempo;}
  accidentals.clear();for(const source of measure.notes){const n=sherlockNotes[sourceIndex],start=abc.length;let symbol='z';if(!n.rest){const [,letter,accidental,octave]=source.name.match(/^([A-G])([#b]?)([0-9])$/);const oct=Number(octave);const key=letter+oct,desired=accidental==='#'?1:accidental==='b'?-1:0,previous=accidentals.has(key)?accidentals.get(key):(['B','E'].includes(letter)?-1:0),prefix=desired===previous?'':desired===1?'^':desired===-1?'_':'=';accidentals.set(key,desired);symbol=prefix+(oct>=5?letter.toLowerCase():letter)+(oct>5?"'".repeat(oct-5):oct<4?','.repeat(4-oct):'');abc+=`"^${tabLabel(n)}"`;}
   abc+=symbol+abcDuration(n.beats)+(n.tie?'-':'');segments.push({sourceIndex,start,end:abc.length,duration:n.beats});abc+=' ';sourceIndex++;
  }
  abc+=measure.number===SHERLOCK_MEASURES.length?'|]':'| ';if(measure.number%barsPerLine===0)abc+='\n';
 }
 return {abc,segments};
}
function renderScore(n=displayedNote){if(practiceView!=='sheet')return;const notes=exploring?[{...n,beats:n.beats||1}]:current.notes;const title=exploring?'Note practice':current.title;const key=exploring?JSON.stringify(notes):current.id;const width=Math.max(280,$('fullScore').clientWidth||600),barsPerLine=current.secret?2:width<520?2:4;scoreKey=key;scoreDirty=false;$('scoreTitle').textContent=title;scoreNodes=[];if(!window.ABCJS){$('scoreError').hidden=false;$('scoreError').textContent='Sheet music could not load. Finger view and playback are still available.';return;}
try{const built=current.secret&&!exploring?buildSherlockScore(title,barsPerLine):buildScore(notes,title,barsPerLine);scoreSegments=built.segments;window.ABCJS.renderAbc('fullScore',built.abc,{add_classes:true,responsive:'resize',staffwidth:width-25,paddingtop:12,paddingbottom:20,paddingleft:10,paddingright:10,scale:1,format:{titlefont:'Georgia 20',annotationfont:'Arial 11'},selectTypes:false,clickListener:(elem)=>{const segment=scoreSegments.find(s=>elem.startChar>=s.start&&elem.startChar<s.end);if(!segment||exploring)return;stop();index=segment.sourceIndex;showNote(current.notes[index]);ensureAudio().then(()=>playTone(current.notes[index]));$('playStatus').textContent=`Note ${index+1} of ${current.notes.length} · tap Play along to continue.`;}});
scoreNodes=Array.from($('fullScore').querySelectorAll('.abcjs-note, .abcjs-rest'));scoreNodes.forEach((el,i)=>{const segment=scoreSegments[i];if(!segment)return;el.dataset.scoreIndex=segment.sourceIndex;el.setAttribute('role','button');el.setAttribute('tabindex','0');const note=notes[segment.sourceIndex];el.setAttribute('aria-label',`Note ${segment.sourceIndex+1}: ${note.rest?'Rest':voices(note).map(v=>`${pitch(v).name}${pitch(v).octave}, ${tabLabel(v)}, ${fingerLabel(v)}`).join(' and ')}`);el.addEventListener('click',()=>{if(exploring)return;stop();index=segment.sourceIndex;showNote(current.notes[index]);ensureAudio().then(()=>playTone(current.notes[index]));$('playStatus').textContent=`Note ${index+1} of ${current.notes.length} · tap Play along to continue.`;});el.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&!exploring){event.preventDefault();stop();index=segment.sourceIndex;showNote(current.notes[index]);ensureAudio().then(()=>playTone(current.notes[index]));}});});$('scoreError').hidden=true;}catch(error){$('fullScore').textContent='';$('scoreError').hidden=false;$('scoreError').textContent='This score could not be drawn. Please use Finger view.';console.error(error);}}
function updateScore(n){if(practiceView!=='sheet')return;const key=exploring?JSON.stringify([{...n,beats:n.beats||1}]):current.id;if(scoreDirty||key!==scoreKey)renderScore(n);const currentIndex=exploring?0:index;scoreNodes.forEach(el=>{const active=Number(el.dataset.scoreIndex)===currentIndex;el.classList.toggle('score-active',active);el.setAttribute('aria-pressed',String(active));});if(current.secret){const active=scoreNodes.find(el=>Number(el.dataset.scoreIndex)===currentIndex),box=$('fullScore');if(active){const r=active.getBoundingClientRect(),b=box.getBoundingClientRect();if(r.top<b.top)box.scrollTop+=r.top-b.top-20;else if(r.bottom>b.bottom)box.scrollTop+=r.bottom-b.bottom+20;}}$('scoreCurrent').textContent=n.rest?`Rest · ${n.beats} beat${n.beats===1?'':'s'}`:voices(n).map(v=>`${pitch(v).name}${pitch(v).octave} · ${tabLabel(v)} · ${fingerLabel(v)}`).join(' + ');}
function setPracticeView(view){practiceView=view;$('fingerStage').hidden=view!=='finger';$('sheetStage').hidden=view!=='sheet';$('fingerView').classList.toggle('selected',view==='finger');$('sheetView').classList.toggle('selected',view==='sheet');$('fingerView').setAttribute('aria-pressed',String(view==='finger'));$('sheetView').setAttribute('aria-pressed',String(view==='sheet'));if(view==='sheet'){renderScore();updateScore(displayedNote);}}
$('fingerView').onclick=()=>setPracticeView('finger');$('sheetView').onclick=()=>setPracticeView('sheet');
let scoreResizeTimer;window.addEventListener('resize',()=>{clearTimeout(scoreResizeTimer);scoreResizeTimer=setTimeout(()=>{scoreDirty=true;if(practiceView==='sheet'){renderScore();updateScore(displayedNote);}},150);});
