const secretButton=document.querySelector('.brand');secretButton.addEventListener('click',event=>{event.preventDefault();clearTimeout(secretClickTimer);secretClicks++;if(secretClicks===3){secretClicks=0;selectLesson('221b');setPracticeView('sheet');$('playStatus').textContent='You found 221B Baker Street. Start slowly and learn one phrase at a time.';}else secretClickTimer=setTimeout(()=>{secretClicks=0;},1500);});
